const MANIFEST = "./__offline-manifest__";
const MATCH = { ignoreSearch: true, ignoreVary: true };
/** a download that fails is tried this many times in all, these many ms apart */
const TRIES = 3;
const RETRY_MS = [1000, 3000];

const sizeOf = (url) => (META[url] ? META[url][1] : 0);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Copies every file the previous deploys' caches hold with the same content (META hash) into this one: a deploy downloads only what changed. */
async function carryOver(cache) {
  const keys = (await caches.keys()).filter((k) => k.startsWith('dronesim-') && k !== CACHE);
  for (const key of keys) {
    const old = await caches.open(key);
    const m = await old.match(MANIFEST);
    if (!m) continue;
    let prev;
    try {
      prev = await m.json();
    } catch {
      continue;
    }
    for (const url of Object.keys(META)) {
      if (!prev[url] || prev[url][0] !== META[url][0]) continue;
      if (await cache.match(url, MATCH)) continue;
      const res = await old.match(url, MATCH);
      if (res) await cache.put(url, res);
    }
  }
}

/** Tells every page (installing workers have no controlled pages yet, hence includeUncontrolled) how far the download is. */
async function tell(p) {
  for (const c of await self.clients.matchAll({ includeUncontrolled: true })) c.postMessage({ type: 'offline-progress', ...p });
}

/**
 * Downloads every one of the urls not cached yet (4 at a time, TRIES tries each), reporting files and bytes after each file
 * (a page gives up on a worker it has not heard from for a while). Resolves with the number that failed.
 */
async function fill(cache, urls, phase) {
  const total = urls.length;
  const totalBytes = urls.reduce((s, u) => s + sizeOf(u), 0);
  let done = 0;
  let failed = 0;
  let bytes = 0;
  const report = () => tell({ phase, done, failed, total, bytes, totalBytes });
  await report();
  const queue = urls.slice();
  const lane = async () => {
    for (let url = queue.shift(); url; url = queue.shift()) {
      let ok = !!(await cache.match(url, MATCH));
      for (let t = 0; !ok && t < TRIES; t++) {
        if (t > 0) await sleep(RETRY_MS[t - 1] || 3000);
        try {
          const res = await fetch(new Request(url, { cache: 'reload' }));
          if (res.ok) {
            await cache.put(url, res);
            ok = true;
          }
        } catch {
          /* offline or a dropped connection: tried again */
        }
      }
      if (ok) bytes += sizeOf(url);
      else failed++;
      done++;
      await report();
    }
  };
  await Promise.all([lane(), lane(), lane(), lane()]);
  return failed;
}

/** Fetches every runtime asset not cached yet, telling the open pages how far it got (a page that asks again gets the end state at once). */
let warming = null;
function warm() {
  if (warming) return warming;
  warming = caches
    .open(CACHE)
    .then((cache) => fill(cache, WARM, 'warm'))
    .finally(() => {
      warming = null;
    });
  return warming;
}

self.addEventListener('message', (e) => {
  if (e.data && e.data.type === 'warm') e.waitUntil(warm());
});

self.addEventListener('install', (e) => {
  e.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      await carryOver(cache).catch(() => undefined);
      // the shell and code must all be in before this worker takes over (as cache.addAll was): one missing file fails the install
      if ((await fill(cache, FILES, 'install')) > 0) throw new Error('offline install incomplete');
      await cache.put(MANIFEST, new Response(JSON.stringify(META), { headers: { 'content-type': 'application/json' } }));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith('dronesim-') && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  if (req.mode === 'navigate') {
    // pages: network first so a new deploy shows up, the cached page when offline (query ignored:
    // /play/?xremu=1 is /play/), else the landing page
    e.respondWith(fetch(req).catch(() => caches.match(req, MATCH).then((r) => r || caches.match('./', { ignoreVary: true }))));
    return;
  }
  // hashed assets, icons, manifest: cache first. ignoreVary: module scripts carry an Origin header the
  // precache requests did not, and hosts answer with Vary: Origin / Accept-Encoding
  if (RUNTIME.test(new URL(req.url).pathname) || ON_DEMAND.test(new URL(req.url).pathname)) {
    // texture maps and the radial bay's files: cache first too, filled on first use (same versioned cache, cleared with it)
    e.respondWith(
      caches.match(req, MATCH).then(
        (r) =>
          r ||
          fetch(req).then((res) => {
            if (res.ok) {
              const copy = res.clone();
              e.waitUntil(caches.open(CACHE).then((c) => c.put(req, copy)));
            }
            return res;
          }),
      ),
    );
    return;
  }
  e.respondWith(caches.match(req, MATCH).then((r) => r || fetch(req)));
});
